package tech.dmj.maintain;
import javafx.application.Application;import javafx.geometry.Insets;import javafx.scene.Scene;import javafx.scene.control.Label;import javafx.scene.layout.*;import javafx.scene.paint.Color;import javafx.scene.text.Font;import javafx.stage.Stage;
/** Native shell; screens and engine integration are added in vertical slices. */
public final class App extends Application {
 private static final String BG="#12161d",PANEL="rgba(28,35,46,0.88)",MUTED="#8996a8",TEAL="#35d0bd";
 @Override public void start(Stage stage){BorderPane root=new BorderPane();root.setStyle("-fx-background-color:"+BG+";-fx-font-family:'IBM Plex Sans','Segoe UI';");VBox side=new VBox(8);side.setPadding(new Insets(24,14,24,14));side.setPrefWidth(236);side.setStyle("-fx-background-color:rgba(18,23,31,0.96);-fx-border-color:#273140;-fx-border-width:0 1 0 0;");Label brand=new Label("MAINTAIN AI");brand.setTextFill(Color.web("#e8eef7"));brand.setFont(Font.font("IBM Plex Sans",20));Label edition=new Label("NATIVE  /  INDUSTRIAL");edition.setTextFill(Color.web(TEAL));edition.setStyle("-fx-font-size:10px;-fx-letter-spacing:2px;");side.getChildren().addAll(brand,edition,new Region());String[] navs={"Dashboard","Machines","Maintenance","Work Orders","Fault Log","AI Assistant","Alerts","Spare Parts","Reports","AI Model Lab","History","Settings","About"};for(int i=0;i<navs.length;i++){Label n=new Label(navs[i]);n.setMaxWidth(Double.MAX_VALUE);n.setPadding(new Insets(11,13,11,13));n.setTextFill(Color.web(i==0?"#eaf7f5":MUTED));n.setStyle(i==0?"-fx-background-color:rgba(53,208,189,0.13);-fx-border-color:transparent transparent transparent "+TEAL+";-fx-border-width:0 0 0 3;-fx-background-radius:8;":"-fx-background-radius:8;");side.getChildren().add(n);}
 VBox header=new VBox(5);header.setPadding(new Insets(26,30,16,30));Label eyebrow=new Label("LOCAL OPERATIONS  /  OVERVIEW");eyebrow.setTextFill(Color.web(TEAL));eyebrow.setStyle("-fx-font-size:10px;-fx-letter-spacing:2px;");Label title=new Label("Dashboard");title.setTextFill(Color.web("#edf2f8"));title.setFont(Font.font("IBM Plex Sans",28));header.getChildren().addAll(eyebrow,title);
 HBox metrics=new HBox(14,metric("REGISTERED MACHINES","—","Equipment registry"),metric("OPEN WORK ORDERS","—","Maintenance queue"),metric("ACTIVE ALERTS","—","Local analytics and rules"),metric("ENGINE STATUS","STARTING","Local engine connection"));metrics.setPadding(new Insets(12,30,18,30));VBox content=new VBox(16);content.setPadding(new Insets(0,30,30,30));VBox a=panel("Operational activity","Local events will appear here."),b=panel("Fleet health","Machine health distribution will appear here.");HBox lower=new HBox(14,a,b);HBox.setHgrow(a,Priority.ALWAYS);HBox.setHgrow(b,Priority.ALWAYS);content.getChildren().addAll(metrics,lower);BorderPane main=new BorderPane();main.setTop(header);main.setCenter(content);root.setLeft(side);root.setCenter(main);Scene scene=new Scene(root,1440,900);stage.setTitle("MAINTAIN AI Native");stage.setMinWidth(1100);stage.setMinHeight(720);stage.setScene(scene);stage.show();}
 private static VBox metric(String h,String v,String hint){VBox b=panel(h,hint);Label n=new Label(v);n.setTextFill(Color.web("#f2f6fa"));n.setFont(Font.font("IBM Plex Mono",30));b.getChildren().add(1,n);b.setPrefHeight(142);HBox.setHgrow(b,Priority.ALWAYS);return b;}
 private static VBox panel(String h,String s){VBox b=new VBox(12);b.setPadding(new Insets(20));b.setStyle("-fx-background-color:"+PANEL+";-fx-background-radius:14;-fx-border-color:#2a3544;-fx-border-radius:14;");Label title=new Label(h);title.setTextFill(Color.web("#dfe7f0"));title.setStyle("-fx-font-size:13px;-fx-font-weight:bold;");Label body=new Label(s);body.setWrapText(true);body.setTextFill(Color.web(MUTED));body.setStyle("-fx-font-size:12px;");b.getChildren().addAll(title,body);return b;}
 public static void main(String[]args){launch(args);}
}
